// Solaria process placement prelude (ADR 0014). Generated by Solaria; don't
// edit. The launcher calls isolate() before anything else: it builds the
// environment the run gets from isolation.json and creates the run's scratch
// directory. Nothing from the caller's environment reaches the run unless
// isolation.json names it.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const win = process.platform === "win32";

// lookup reads a variable the way the OS does: case-insensitively on
// Windows.
function lookup(env, name) {
  if (!win) return env[name];
  const want = name.toUpperCase();
  for (const [k, v] of Object.entries(env)) {
    if (k.toUpperCase() === want) return v;
  }
  return undefined;
}

function which(bin, pathVar, pathext) {
  const exts = win ? ["", ...(pathext || ".COM;.EXE;.BAT;.CMD").split(";").filter(Boolean)] : [""];
  for (const dir of (pathVar || "").split(path.delimiter)) {
    if (!dir) continue;
    for (const ext of exts) {
      const p = path.join(dir, bin + ext);
      try {
        if (!fs.statSync(p).isFile()) continue;
        if (!win) fs.accessSync(p, fs.constants.X_OK);
        return p;
      } catch {
        // Not here; keep looking.
      }
    }
  }
  return null;
}

// parseDotenv reads a dotenv file as Solaria does (internal/secrets).
export function parseDotenv(text) {
  const out = {};
  const lines = text.split(/\r?\n/);
  for (let n = 1; n <= lines.length; n++) {
    let line = lines[n - 1].trim();
    if (line === "" || line.startsWith("#")) continue;
    if (line.startsWith("export ")) line = line.slice("export ".length);
    const eq = line.indexOf("=");
    const name = eq < 0 ? "" : line.slice(0, eq).trim();
    if (eq < 0 || name === "") throw new Error(`line ${n}: want NAME=value`);
    let value = line.slice(eq + 1).trim();
    if (value.length >= 2 && value[0] === "'" && value.at(-1) === "'") {
      value = value.slice(1, -1);
    } else if (value.length >= 2 && value[0] === '"' && value.at(-1) === '"') {
      try {
        value = JSON.parse(value);
      } catch (err) {
        throw new Error(`line ${n}: ${err.message}`);
      }
    } else {
      const i = value.indexOf(" #");
      if (i >= 0) value = value.slice(0, i).trim();
    }
    out[name] = value;
  }
  return out;
}

// isolate returns the run's environment, its scratch directory, and a
// cleanup function that removes the scratch directory. cacheDir holds
// package downloads across runs.
export function isolate(spec, { cacheDir }) {
  const caller = { ...process.env };
  const env = {};
  for (const name of spec.pass) {
    const v = lookup(caller, name);
    if (v !== undefined && v !== "") env[name] = v;
  }

  const dirs = [path.dirname(process.execPath)];
  const missing = [];
  for (const bin of spec.binaries) {
    const p = which(bin, lookup(caller, "PATH"), lookup(caller, "PATHEXT"));
    if (p) dirs.push(path.dirname(p));
    else missing.push(bin);
  }
  if (missing.length > 0) throw new Error(`not found on PATH: ${missing.join(", ")}`);
  if (win) {
    const root = lookup(caller, "SYSTEMROOT") || "C:\\Windows";
    dirs.push(path.join(root, "System32"), root);
  } else {
    dirs.push("/usr/bin", "/bin");
  }
  env.PATH = [...new Set(dirs)].join(path.delimiter);

  let values = caller;
  let where = "the environment variables";
  if (spec.dotenv) {
    where = spec.dotenv;
    let text = "";
    try {
      text = fs.readFileSync(spec.dotenv, "utf8");
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
    }
    try {
      values = parseDotenv(text);
    } catch (err) {
      throw new Error(`${spec.dotenv}: ${err.message}`);
    }
  }
  const unset = spec.secrets.filter((n) => !lookup(values, n));
  if (unset.length > 0) throw new Error(`secrets not set in ${where}: ${unset.join(", ")}`);
  for (const n of spec.secrets) env[n] = lookup(values, n);

  Object.assign(env, spec.set);

  const root = fs.mkdtempSync(path.join(os.tmpdir(), "solaria-run-"));
  for (const [name, rel] of Object.entries(spec.scratch)) {
    const dir = path.join(root, ...rel.split("/"));
    fs.mkdirSync(dir, { recursive: true });
    env[name] = dir;
  }
  for (const [name, rel] of Object.entries(spec.cache)) {
    const dir = path.join(cacheDir, ...rel.split("/"));
    fs.mkdirSync(dir, { recursive: true });
    env[name] = dir;
  }
  const cleanup = () => fs.rmSync(root, { recursive: true, force: true });
  return { env, root, cleanup };
}

// adopt replaces this process's own environment with env, so nothing it
// starts can inherit the caller's.
export function adopt(env) {
  for (const k of Object.keys(process.env)) delete process.env[k];
  Object.assign(process.env, env);
}
